-- Canonical export recovered read-only from Staging migration history.
-- Version: 20260831074642; name: esg_evidence_review_workbench

create or replace view public.admin_esg_evidence_workbench with (security_invoker=true) as select a.id,a.enterprise_id,coalesce(e.display_name,e.legal_name,'企業夥伴') as enterprise_name,a.title,a.period_label,a.status,a.report_ready,a.updated_at,q.export_ready,q.quality_issues,c.source_type,c.source_reference,c.source_verified,(a.status='approved' and a.report_ready and q.export_ready and coalesce(c.source_verified,false)) as delivery_ready from public.enterprise_esg_assets a left join public.enterprises e on e.id=a.enterprise_id left join public.enterprise_esg_export_quality q on q.id=a.id left join public.enterprise_esg_evidence_chain c on c.asset_id=a.id; create index if not exists idx_enterprise_esg_assets_review on public.enterprise_esg_assets(status,report_ready,updated_at desc); create or replace function public.admin_set_esg_evidence_review(p_asset_id uuid,p_report_ready boolean,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_actor uuid:=auth.uid(); begin if v_actor is null or not exists(select 1 from public.admin_roles where user_id=v_actor and role_key in ('super_admin','admin','outcome_reviewer','enterprise_reviewer')) then raise exception 'insufficient_privilege'; end if; update public.enterprise_esg_assets set report_ready=p_report_ready,updated_at=now() where id=p_asset_id and status='approved'; if not found then raise exception 'asset_not_approved'; end if; insert into public.audit_logs(actor_user_id,actor_role,action,subject_type,subject_id,note) values(v_actor,'outcome_reviewer',case when p_report_ready then 'esg_report_ready' else 'esg_report_hold' end,'enterprise_esg_asset',p_asset_id::text,p_note); end; $$; revoke all on function public.admin_set_esg_evidence_review(uuid,boolean,text) from public,anon; grant execute on function public.admin_set_esg_evidence_review(uuid,boolean,text) to authenticated;
